(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["non"] = {"ui":{"skip":"Hlaupa til efnis","back":"← Aftr til AI-gile","lang.button":"Tunga: {name}","lang.dialog":"Veldu tungu","lang.search":"Leita at tungum","lang.none":"Engin tunga samsvarar","lang.notYet":"{name} er eigi þýdd enn","theme.aria":"Skipta yfirbragði: ljóst, dökkt eða svart","theme.toLight":"Skipta til ljóss yfirbragðs","theme.toDark":"Skipta til dökks yfirbragðs","theme.toBlack":"Skipta til svarts yfirbragðs (sannsvart, mjúkt fyrir OLED-skjái)","words.underline":"Strika undir þessi orð á síðunni","words.underlineHelp":"Hald músinni yfir orði með deplóttri línu, eða drep á þat, til at sjá hvat þat merkir.","index.title":"AI-gile: gervigreindarsveit þín, á einu borði","index.description":"AI-gile er kanban-borð fyrir gervigreindar-kóðasveitir. Þær vinna meðan þú sefr; þú færð einn stuttan haug af hlutum at ákveða, prófa ok samþykkja.","hero.logoAlt":"Tákn AI-gile-borðsins","hero.h1.html":"Gervigreindarsveit þín, á einu&nbsp;borði.","hero.alpha":"🐣 Lokat for-alfa","hero.alphaTitle":"Snemma ok ólokit: þökk fyrir at reyna!","hero.lede":"Þær smíða meðan þú sefr. Þú vaknar við einn stuttan haug: nokkrar spurningar, nokkra hluti at prófa, einn fjólubláan tígul eða tvá. Smelltu, samþykktu, ok aftr til kaffis þíns.","dl.windows":"Windows-forrit","dl.browser":"Rek þat í vafra þínum","dl.messenger":"📱 Messenger fyrir síma þinn","dl.soon":"Kemr brátt","dl.notify":"🔔 Seg mér, þá er þat opnast","dl.notifySmall":"Alfa eða beta","hero.secondary":"Agile, en sveitin þarf aldri kaffi á stand-up. (Þær halda stand-up þó.)","pitch.h2":"AI-gile í svá mörgum orðum sem þú vilt","pitch.lede":"Veldu lengd, frá einu orði til 144. Hver lengd er sín eigin lýsing, rituð fyrir þá stærð. Dragðu sleðann eða notaðu örvalyklana.","pitch.rangeLabel":"Lengd í orðum","pitch.dice":"🎲 önnur gerð","pitch.words.one":"{n} orð","pitch.words.other":"{n} orð","pitch.letters.one":"{n} stafr","pitch.letters.other":"{n} stafir","pitch.chars.one":"{n} tákn","pitch.chars.other":"{n} tákn","count.line.html.one":"{n} spjald á borðinu nú","count.line.html.other":"{n} spjöld á borðinu nú","people.humans.html.one":"👥 {n} maðr","people.humans.html.other":"👥 {n} menn","people.agents.html.one":"🤖 {n} erindreki","people.agents.html.other":"🤖 {n} erindrekar","people.working.html.one":"⚡ {n} at verki nú","people.working.html.other":"⚡ {n} at verki nú","pre.title":"AI-gile: eitthvat er í smíðum","pre.description":"Hér er eitthvat í smíðum: borð þar sem gervigreindarsveitir smíða þat er þú biðr um, ok kenna þér á leiðinni. Lokat for-alfa með vinum at sinni.","pre.h1":"Hér er eitthvat í smíðum. 🤫","pre.line":"Borð þar sem gervigreindarsveitir smíða þat er þú biðr um, ok kenna þér á leiðinni. Lokat for-alfa með vinum at sinni.","pre.btn":"🔔 Seg mér, þá er þat opnast","pre.peek":"Bak við glerit: hit sanna borð, lífs. Hvert spjald er litaðr strengr.","pre.peekFake":"Bak við glerit: svá lítr borð at verki út.","features.aria":"Hvat þat gerir","f.pile.h":"Einn haugr handa þér","f.pile.html":"<b>Til þín</b> geymir allt sem bíðr þín, í öllum verkum: spurningar, hluti at prófa, störf er aðeins maðr má vinna. Röð þín segir hvat er næst ok hve lengi þat tekr.","f.sleep.h":"Sveitir er vinna meðan þú sefr","f.sleep.p":"Hvert verk hefr leiðtoga ok sveit gervigreindar-erindreka. Gerðu ummæli á spjald ok sveitin vaknar, vinnr verkit ok skilar því aftr með skrefum er þreyttr maðr má fylgja.","f.tester.h":"Gervigreindarprófari lítr fyrst á","f.tester.p":"Áðr en nokkut kemr til þín, fylgir prófari skrefunum í eftirmynd forritsins ok sýnir hvat hann sá, með skjámynd. Flettu gegnum þau er stóðust ok samþykktu með einum smelli.","f.proof.h":"Sannanir, eigi heit","f.proof.p":"Hver afhending sýnir hvat breyttist: skrárnar, muninn, skjámyndirnar. Þú þarft eigi at opna hvert forrit til at sjá hvárt því sé lokit.","f.chat.h":"Ræð við leiðtoga þína","f.chat.p":"Rönd í Discord-stíl: eitt tákn fyrir hvert verk, fjólubláir tíglar fyrir þat er þarfnast þín. Send leiðtoga hugmynd; hann gerir hana at spjöldum ok áætlun, með ✅ Go-hnappi.","f.tidy.h":"Heldr sjálfr reglu","f.tidy.p":"Skyld spjöld renna saman, ruglingsleg heiti eru löguð, ok tákna-athugun heldr kóðanum mjóum. Færra at skipta milli, minna at hugsa um.","f.private.h":"Þitt, á þinni eigin tölvu","f.private.li1":"Borðit gengr á þinni eigin vél ok svarar aðeins þér.","f.private.li2":"Einkaskilaboð milli manna eru dulrituð frá enda til enda.","f.private.li3":"Engir reikningar, engir eltarar, engar kökur.","f.lang.h":"Á þinni tungu","f.lang.p":"Yfir 120 tungur, frá norrœnu, velsku ok japönsku til sjóræningja, Yoda ok klingonsku, með skjótum rofa aftr til ensku fyrir iðnorð.","f.service.h":"Frá hugmynd til sannrar þjónustu","f.service.p":"Smíðaðir þú nökkut með gervigreind er menn nota nú? Merk þat sem þjónustu, ok taflan hjálpar þér at reka hana vel: uppitímaathuganir, opinber stöðusíða, atvik með eftirrannsókn, breytingar er þurfa Gakk, afrit athuguð hvern dag. Hjálpin kennir hvert skref á leiðinni.","msgr.h2":"AI-gile Messenger: sveit þín í pússi þínum","msgr.p1":"Mæl við gervigreindarsveit þína án þess at opna borðit. Spjalla við verkforingja þína ok vini þína, ok sé prófskref spjalds ok svara þeim, allt ór síma þínum.","msgr.p2":"Til at para hann, skanna QR-kóða á borði þínu. Fyrsta sinn? Vingjarnligt sýnispjall sýnir þér allt.","msgr.when":"Android fyrst, síðan vefútgáfa fyrir síma ok iPhone.","msgr.who":"Verkforingi þinn","msgr.b1":"Bótin fyrir dökkan hátt er búin. Viltu prófskrefin?","msgr.b2":"Já, gjarna!","msgr.b3":"1. Opna Uppsetning. 2. Vel Dökkt. Lítr þat rétt út?","tl.aria":"Tímalína frá fyrsta samtali til vegvísis","tl.h2":"Frá fyrsta spjalli til þess er næst kemr","tl.lede":"Sannar dagsetningar ok stundir, á þínu tímabelti. Eftir í dag er þat áætlun, án heitinna daga.","tl.today":"Í dag","tl.planned":"áætlat","tl.doing":"í verki","tl.cards.one":"{n} spjald","tl.cards.other":"{n} spjöld","join.h2":"Gakk í lið","join.lede":"AI-gile er smíðat af skeggjuðum undarligum manni með AuDHD ok nökkurum hugarstríðum, ok mörgum þolinmóðum erindrekum. Enn er þat einkamál, lokat alfa með vinum. Viltu reyna þá er þat opnast?","join.btn":"Skrá áhuga","join.small":"Vér sendum þér póst, ekki meira","footer.tag":"AI-gile. Engir eltarar, engar kökur, ekkert stand-up-kaffi.","footer.licence":"Starfsleyfi","footer.status":"Staða","footer.privacy":"Hvat vér geymum","footer.thanks":"Símtöl með þökk til ChilledChat","form.sending":"Sendi…","form.failed":"Þat tókst eigi: reyn aftr síðar.","form.offline":"Náði eigi til AI-gile: reyn aftr síðar.","form.keep":"Vér notum þetta einungis til at svara þér, ok eyðum því síðan. Engir eltarar, engar kökur.","form.keepLink":"Hvat vér geymum","interest.title":"AI-gile: seg mér þá er alfa opnast","interest.description":"Skildu eftir netfang þitt til at heyra þá er lokat alfa eða beta AI-gile opnast.","interest.h1":"🔔 Seg mér, þá er þat opnast","interest.lede":"AI-gile er í lokuðu for-alfa. Skildu eftir netfang þitt, ok vér skrifum einu sinni, þá er rúm er fyrir þik.","interest.email":"Netfang þitt","interest.which":"Hvert próf?","interest.alpha":"Lokat alfa: snemma, hrátt, margar breytingar","interest.beta":"Beta: stöðugra, síðar","interest.both":"Hvárt sem er, hvat sem fyrst kemr","interest.submit":"Settu mik á listann","interest.thanks":"Þökk! Þú ert á listanum.","licence.title":"AI-gile: starfsleyfi","licence.description":"Notar þú AI-gile í fyrirtæki þínu? Sæktu um ókeypis starfsleyfi.","licence.h1":"📜 Starfsleyfi","licence.lede":"Notar þú AI-gile í vinnu? Seg oss hverr þú ert ok hvat þú gerir. Ef þat gerir nokkut gott, er leyfit ókeypis.","licence.company":"Fyrirtæki","licence.website":"Vefsíða","licence.what":"Hvat þú gerir","licence.how":"Hversu þat hjálpar heiminum","licence.email":"Netfang","licence.submit":"Sækja um","licence.thanks":"Þökk! Vér svörum með pósti.","status.title":"Staða AI-gile","status.h1":"Staða AI-gile","status.quiet":"Allt er kyrrt","status.intro":"Starfar AI-gile nú? Þessi síða athugar vefinn, borðadeilingu, símtöl ok niðrhalit á 5 mínútna fresti.","status.up":"Starfar (svaraði á {ms} ms)","status.slow":"Svaraði eigi síðustu athugun, reyni aftr","status.down":"Niðri: svaraði eigi tveim síðustu athugunum","status.svc.web":"Vefr","status.svc.web.offers":"Þessi vefr: hvat AI-gile er, ok áhugaformit","status.svc.boards":"Borðadeiling","status.svc.boards.offers":"Opin borð, skilaboð milli vina ok boð","status.svc.calls":"Símtöl","status.svc.calls.offers":"Rödd, myndband ok skjádeiling í AI-gile","status.svc.download":"Niðrhal","status.svc.download.offers":"Windows-uppsetningin ok boðstenglar","status.checking":"Athuga…","status.offline":"Næ eigi til stöðuþjónustunnar nú (reyni aftr)","status.updated":"nýjat {ago}","status.justNow":"rétt nú","status.min":"{n}m síðan","status.hours":"{n}t síðan","status.days":"{n}d síðan","privacy.title":"AI-gile: hvat vér geymum","privacy.h1":"Hvat vér geymum","privacy.lede":"Í stuttu máli: aðeins þat er þú sendir oss, ok eigi lengi.","privacy.only":"Aðeins þat er þú sendir oss: þat er þú ritar í form, svá sem netfang þitt. Ekkert annat um þik.","privacy.sealed":"Þat er innsiglat svá at þjónn várr fái eigi lesit þat: í vafra þínum áðr en þat ferr (í eldri vafra, þegar er þat kemr). Aðeins várt eigit borð má opna þat.","privacy.server":"Því er eytt af þjóninum jafnskjótt sem þat nær borði váru. Allt er þar liggr enn eftir 30 daga er eytt engu at síðr.","privacy.board":"Vér geymum þat á borði váru aðeins unz vér höfum svarat þér, ok eyðum því þar síðan.","privacy.none":"Engir eltarar, engar kökur, engar mælingar.","privacy.local":"Mál þitt ok val milli ljóss ok dökks haldast í þínum eigin vafra. Þau eru aldri send oss.","privacy.ask":"Viltu at því sé eytt fyrr? Svara bréfi váru ok seg svá.","live.h2":"Sjá þat byggjask, lífs","live.caption":"Hvert spjald er hulit: þú sér líking verksins, eigi orðin.","live.watching.one":"lífs: {n} sér","live.watching.other":"lífs: {n} sjá","live.last.now":"Síðasta spjald var fært rétt nú","live.last.min.one":"Síðasta spjald var fært fyrir {n} mín.","live.last.min.other":"Síðasta spjald var fært fyrir {n} mín.","live.last.hour.one":"Síðasta spjald var fært fyrir {n} stund","live.last.hour.other":"Síðasta spjald var fært fyrir {n} stundum","live.last.day.one":"Síðasta spjald var fært fyrir {n} degi","live.last.day.other":"Síðasta spjald var fært fyrir {n} dögum","live.offline":"Lífs taflan hvílisk um stund. Kom aptr brátt.","live.cols":"Backlog|Til gerðar|Í verki|Sveitin lítr á|Til þín at testa|Til sveitar|Lokit"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Erindrekar.","Falit."]},{"n":2,"texts":["Erindrekar, skipaðir.","Hugmyndir, smíðaðar.","Erindrekar vinna."]},{"n":3,"texts":["Kanban fyrir erindreka.","Hugmyndir verða eiginleikar.","Ókeypis, heima, prófat."]},{"n":5,"texts":["Borð þar er erindrekar smíða.","Þú ritar spjöld. Erindrekar smíða.","Ókeypis, heima, prófat, lítit skrýtit."]},{"n":8,"texts":["Ókeypis kanban-borð þar er gervigreindar-erindrekar vinna öll verkin.","Rit eina hugmynd. Erindrekar smíða hana. Þú samþykkir.","Agile fyrir einn mann ok marga þolinmóða erindreka."]},{"n":13,"texts":["Kanban-borð á tölvu þinni þar er gervigreindar-erindrekar taka spjöldin upp ok vinna þau.","Rit hugmynd. Sveit erindreka smíðar hana. Síðan lítr prófari á hana fyrir þik.","Ókeypis, engir reikningar né eltarar: borð, nokkrir erindrekar, ok þú ræðr öllu."]},{"n":21,"texts":["AI-gile er kanban-borð til at vinna með gervigreindar-kóðaerindrekum. Þeir taka spjöldin upp, hvert af öðru; þú prófar þau ok samþykkir.","Hvert verk fær leiðtoga ok sveit gervigreindar-erindreka. Gerðu ummæli á hvert spjald, ok þá tekr sveitin til starfa.","Ókeypis einkaborð til verka, er gengr á þinni eigin tölvu. Verkamennirnir eru erindrekar. Sá er segir já, ert þú."]},{"n":34,"texts":["Þú leggr hugmyndir á borð. Sveit gervigreindar-erindreka gerir þær at starfandi eiginleikum, prófar þá ok skilar þeim aftr með skrefum til at reyna. Ekkert telst lokit fyrr en þú segir svá.","AI-gile er heimagert kanban-borð er Rich smíðaði með mikilli hjálp erindreka þeirra er þat nú stýrir. Þat er ókeypis, gengr á tölvu þinni ok er deilt með vinum, eigi selt.","Hugsaðu þér venjulegt kanban-borð, með dálkum frá Backlog til Lokit, nema at spjöldin eru tekin af gervigreindar-erindrekum. Þeir segja frá framvindu, spyrja þá er þeir sitja fastir, ok bíða ávallt eftir þumli þínum upp."]},{"n":55,"texts":["AI-gile er kanban-borð þar er sveitin er gerð af gervigreindar-erindrekum. Hvert verk hefr leiðtoga er áætlar verkit ok hjálparmenn er smíða þat. Þá er eiginleiki er búinn, reynir gervigreindar-prófari hann ok tekr skjámynd, ok þá lendir hann á hauginum þínum. Samþykktu hann, eða gerðu ummæli, ok þeir vinna hann upp aftr.","Þat hófst sem leið eins manns til at halda utan um margar kóðalotur með gervigreind í senn, ok óx at réttu borði. Þat gengr á vél þinni, krefst engra reikninga ok hefr enga eltara. Þat er ókeypis fyrir vini ok forvitna. Þat er ok ólokit, svá búst við hrjúfum brúnum ok einni óvæntri uppákomu.","Hér er heiðarlega útgáfan. Þú verðr enn at eiga hugmyndirnar, ok þú verðr enn at líta á árangrinn. Þat er AI-gile gerir, er allt þar í milli: þat heldr spjöldunum í röð, vekr réttan erindreka þá er þú gerir ummæli, sýnir nákvæmlega hvat breyttist, ok safnar öllu í einn stuttan haug handa þér."]},{"n":89,"texts":["AI-gile er ókeypis kanban-borð er þú rekr á þinni eigin tölvu. Í stað manna hefr hvert verk sveit gervigreindar-erindreka: leiðtoga er gerir hugmyndir þínar at spjöldum ok áætlun, ok hjálparmenn er taka spjöldin í forgangsröð. Þá er eitthvat er smíðat, fylgir gervigreindar-prófari prófunarskrefunum ok sýnir þér hvat hann sá. Síðan bíðr þat í einum haug er heitir Til þín. Þú samþykkir þat, eða þú gerir ummæli ok sveitin reynir aftr. Ekkert kemst nokkurn tíma í Lokit án þín.","Nokkrir eiginleikar er þú væntir kannski eigi. Næturvörðr heldr Til gerðar-dálkinum fullum meðan þú sefr ok velr spjöld er þurfa eigi svar frá þér. Teljari sýnir hversu mikit erindrekarnir hafa notat í dag ok þessa viku, ok Engin tákn-hátr segir þeim at hætta at eyða. Þú mátt senda vinum skilaboð, ok einkaskilaboð eru dulrituð frá enda til enda. Borðit talar um 120 tungur, þar á meðal norrœnu, sjóræningja ok klingonsku. Ekkert af þessu kostar eyri, ok engi reynir at selja þér þat heldr.","AI-gile er lítit, persónulegt verk, eigi fyrirtæki. Rich vildi gæta margra gervigreindar-kóðaverka án þess at opna hvert forrit til at líta á þau, svá hann ok erindrekarnir smíðuðu borð til þess, ok notuðu síðan borðit til at smíða afganginn af sér sjálfu. Þat er í lokuðu for-alfa, sem merkir at þat virkar, mestanpart, fyrir fáeina vini. Hér er engin verðsíða, ekkert fréttabréf ok engin vaxtaráætlun. Ef þetta hljómar gagnlegt, mátt þú biðja um at reyna þat þá er þat opnast örlítit meira."]},{"n":144,"texts":["AI-gile er kanban-borð fyrir einn mann ok marga gervigreindar-erindreka. Þat gengr á þinni eigin tölvu ok er alveg ókeypis. Þú bætir við verkum, ok hvert verk fær leiðtoga ok litla sveit. Þú ræðr við leiðtogann, líkt ok á Discord, ok lýsir hugmynd; leiðtoginn gerir hana at spjöldum ok áætlun, ok bíðr þess at þú ýtir á Go. Sveitin vinnr sig gegnum spjöldin í forgangsröð, með einföldu skipanalínutóli gerðu fyrir mállíkön. Áðr en nokkut kemr aftr til þín, fylgir gervigreindar-prófari skrefunum í eftirmynd forritsins ok festir við skjámynd. Lokit verk lendir á hauginum þínum með breyttum skrám ok muninum. Þú samþykkir þat, eða þú skilr eftir ummæli, ok sveitin vaknar ok reynir aftr. Aðeins þú mátt færa spjald til Lokit.","Dagr með AI-gile, í grófum dráttum. At kveldi skilr þú eftir nokkur ummæli: þessi hnappr er á röngum stað, sá listi ætti at vera raðaðr, gætum vér fengit dökkan hátt. Þú ferr at sofa. Erindrekarnir lesa ummælin, gera breytingarnar, prófa þær ok skila þeim aftr til þín. Ef Til gerðar tæmist, fyllir næturvörðrinn þat úr backlog með spjöldum er þurfa ekkert svar frá þér. At morgni er þar einn stuttr haugr: nokkrar spurningar ok fáeinir hlutir at reyna, hver með skrefum er syfjaðr maðr má fylgja ok skjámynd af því at þat virkar. Þú smellir þig gegnum, samþykkir góðu spjöldin ok sendir hin aftr. Teljari sýnir hvat allt þetta notaði, ok Engin tákn-hátr er til fyrir magrar vikur. Síðan etr þú morgunverð, er erindrekarnir fá enn eigi hjálpat með.","Fyrst, hvat AI-gile er eigi. Þat er eigi sprotafyrirtæki, þat er eigi til sölu, ok engi safnar gögnum þínum. Þat er ókeypis borð er gengr á tölvu þinni, án reikninga, eltara eða kaka. Hvat þat er: einn snyrtiligr staðr til at sjá öll gervigreindar-kóðaverk þín senn, með sveit erindreka er vinnr spjöldin ok þik er tekr ákvarðanirnar. Þat steypir skyldum spjöldum saman, lagar ruglingsleg heiti ok fylgist með hversu mjór kóðinn helzt. Þat talar um 120 tungur, frá norrœnu til sjóræningja ok klingonsku. Vinir mega senda hverr öðrum skilaboð, einkaliga ok dulrituð. Þat var smíðat af Rich ok mörgum þolinmóðum erindrekum, er mestanpart notuðu þat sjálfir. Þat er í lokuðu for-alfa, svá þat er hrjúft sums staðar. Ef þat hljómar skemmtiligt, bið vel, ok kannski kemst þú snemma inn."]}],"quips":{"1":"Eitt orð. Djarft. Kannski of djarft.","3":"Þrjú orð. Þegar heiðarlegra en flestar vörusíður.","8":"Átta orð. Enn styttra en stand-up.","21":"Lengdirnar eru annars story points. Auðvitað eru þær þat.","55":"Fimmtíu ok fimm orð. Tvö spjöld lukust meðan þú last þetta.","144":"Þat var hit langa. Ekkert 233 er til. Erindrekarnir eru farnir at sofa."}},"timeline":{"first-idea.name":"Hin fyrsta hugmynd","first-idea.line":"Hit allra fyrsta samtal, áðr en nokkur kóði var til.","first-board.name":"Hit fyrsta borð","first-board.line":"Borð er heldr utan um sína eigin smíð: spjöld, dálka, draga ok sleppa, verk.","team-roles.name":"Sveit ok hlutverk","team-roles.line":"Erindrekasnið, sveitarsnið, rými ok hverr gerir hvat.","install.name":"Uppsetning ok útgáfur","install.line":"Zip-skrá er vinr má setja upp, sjálfnýjun, rásir ok afturhvarf.","usage-saver.name":"Notkunarsparnaðr","usage-saver.line":"Mæla hvat keyrslur kosta, halda kóðanum mjóum, spara mörk þín.","friends.name":"Vinir ok deiling","friends.line":"Einkaskilaboð, dulrituð miðlun, boð, hlutverk ok sameiginleg verk.","languages.name":"Tungur","languages.line":"Hver skjátexti í tungumálsskrá, með hollenzku ok flæmsku fyrst.","ai-tester.name":"Gervigreindarprófari","ai-tester.line":"Prófari lítr á hverja afhending fyrst ok sýnir hvat hann sá.","website.name":"Vefsíðan","website.line":"aigile.lol, forsmekkrinn ok þessi tímalína.","streaming.name":"Spjall ok streymi","streaming.line":"Discord, Twitch, OBS, streymishátr, GIF ok tjáknmyndir.","no-ai.name":"Útgáfa án gervigreindar","no-ai.line":"Borð fyrir þá er kóða án gervigreindar, ok opinber borð.","night-watch.name":"Næturvarðhald","night-watch.line":"Vörðr ok Scrum-meistari halda sveitunum við efnit meðan þú sefr.","p-more.name":"Allt annat","p-more.line":"Minni hugmyndir er enn bíða síns tíma.","p-android.name":"Sími ok Android","p-android.line":"Nálgast borð þitt úr síma, síðan sérstakt Android-forrit.","p-release.name":"Alfa ok lengra","p-release.line":"Lokat alfa, hin lifandi vefsíða, síðan beta.","p-languages.name":"Fleiri tungur","p-languages.line":"130 tungur, ok kafhamr fyrir þá er nema.","p-engines.name":"Fleiri gervigreindarvélar","p-engines.line":"Vel Claude, Codex, Gemini, Copilot eða Cursor fyrir hvern erindreka.","p-pro.name":"Atvinnuháttr","p-pro.line":"Áhættumerki, sameiningarhlið, atvikaspjöld ok handrið.","p-self.name":"Gæta þín","p-self.line":"Þreytuhátr, sjálfsumönnunaráminningar ok 4:20.","p-servers.name":"Þjónar ok umfang","p-servers.line":"Almennar þjónastillingar, hlutverk ok áætlun fyrir vöxt.","p-livestream.name":"Streymisviðbætr","p-livestream.line":"Twitch-spjall, eigin tjáknmyndir ok opinbert beint yfirlit."},"words":{"button":"📖 Iðnorð","h":"📖 Orð skýrð","intro":"Orðin er þú hittir í AI-gile, í einföldu máli: at smíða, at breyta með öryggi, at halda því í gangi fyrir þá er nota þat, ok at starfa sem sveit með gervigreind.","search":"Leita orðs…","none":"Ekkert orð samsvarar því.","close":"Loka","count":{"one":"{count} orð","other":"{count} orð"},"groups":[{"id":"build","name":"🛠️ At smíða"},{"id":"change","name":"🔀 At breyta með öryggi"},{"id":"run","name":"🛎️ At reka þjónustu"},{"id":"team","name":"🤝 At starfa sem sveit (ok með gervigreind)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Mappa verksins með kóða ok allri sögu commits, oftast einnig geymd á GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Sérstök starfslína í kóðanum, svá at breyta megi án at snerta aðalgerðina.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Vistuð ljósmynd kóðans, með stuttri athugasemd um hvat breyttisk. Þú getr ávallt snúit aftr til einnar.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"At senda vistaðar ljósmyndir (commits) úr þessi tölvu upp til GitHub, svá at þær séu varðar ok deildar."},{"id":"merge","g":"build","word":"Merge","text":"At sameina breytingar greinar aftr í aðalgerðina."},{"id":"pr","g":"build","word":"Pull request","text":"Beiðni um at breytingar greinar séu skoðaðar ok sameinaðar í aðalgerðina.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"At taka til í kóðanum án at breyta hvat hann gerir: smærri skrár, skýrari heiti, minni endrtekning."},{"id":"bug","g":"build","word":"Bug","text":"Eitthvat er eigi starfar sem skyldi.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"At reyna lokit verk til at sjá at þat geri sem beðit var, áðr en þú samþykkir þat.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Stytting á quality assurance (gæðatrygging): sjálfvirkar prófanir er renna áðr en nökkut fer í gang. Þá er QA er rautt, hefir nökkut brugðizk, ok þat má eigi fara í gang unz þat er lagat.","also":["gæðaprófanir","gæðaprófun"]},{"id":"deploy","g":"change","word":"Deploy","text":"At setja nýja gerð í gang, t.d. á þjón þar er menn nota hana."},{"id":"release","g":"change","word":"Útgáfa","text":"Nefndr böggull lokins verks er ferr í gang saman, með stuttum skýringum um hvat breyttisk. 🚀 Útgáfur rita skýringarnar af lokinum spjöldum.","also":["útgáfur","útgáfu","útgáfunnar"]},{"id":"rollback","g":"change","word":"Rúlla aftr","text":"At snúa aftr til hinnar síðustu útgáfu er virkaði, þá er ný veldr vandræðum. Í AI-gile gerir þat gátlista af afturkallsskrefunum er rituð eru á hverja breytingu.","also":["aftrrúllun","rúllat aftr","rollback"]},{"id":"live","g":"change","word":"Í gangi","text":"Hin sanna útgáfa er menn nota, eigi afrit til at reyna hluti á. Hugbúnaðarsmiðir kalla þat ok production.","also":["fer í gang","fara í gang","production"],"noTip":1},{"id":"change","g":"change","word":"Breyting","text":"Ætluð breyting á nökkuru er menn treysta á, rituð fyrst: hvat, hví, áhættan, hvenær, ok hversu aftr taka. Hef eina með 🔀 Bera upp breytingu.","also":["breytingar","breytingu","breytingarbeiðni","breytingarbeiðnir"],"noTip":1},{"id":"risk","g":"change","word":"Áhætta","text":"Nökkut er farit gæti illa, metit eptir því hversu líklegt ok hversu illt þat yrði. ⚠️ Áhættur geyma þær í einum lista, hæsta mat fyrst, hverja með degi til at líta á aftr.","also":["áhættur","áhættu","áhættuskrá"]},{"id":"chgwin","g":"change","word":"Breytingagluggi","text":"Tímarnir er breytingar mega fara í gang, svá sem kyrrt þriðjudagskveld. Utan glugga má breytingaspjald eigi ljúkask, nema þat sé neyð.","also":["breytingagluggar","glugga","gluggi"]},{"id":"gonogo","g":"change","word":"Gakk / eigi gakk","text":"Skjót atkvæðagreiðsla rétt áðr en breyting ferr í gang: hverr er samþykkja skal segir Gakk eða Eigi gakk. Hon ferr aðeins fram þá er þeir eru sáttir.","also":["go/no go","go-no-go","gakk/eigi gakk"]},{"id":"approval","g":"change","word":"Samþykki","text":"At bíða já áðr en verk hefsk. Spjald er vinr berr upp, eða breyting, bíðr í ✅ Samþykki unz þú samþykkir eða hafnar því.","also":["samþykkis","samþykkja"]},{"id":"quiettime","g":"change","word":"Kyrr tími","text":"Tímaskeið, svá sem straumr, sýning eða nóttin, er ekkert ferr í gang. Sveitirnar halda áfram at starfa ok prófa, en at fara í gang bíðr unz því lýkr. Annars staðar kallask þat breytingafrost.","also":["kyrrir tímar","kyrrum tíma","breytingafrost"]},{"id":"service","g":"run","word":"Þjónusta","text":"Nökkut er þú smíðaðir ok menn treysta á, svá sem vefsetr eða forrit, er gætt er svá at þat virki áfram. Merk við „Þetta verkefni er þjónusta“ ok seg hvat hon býðr, hverr hana notar ok hverr er á vakt.","also":["þjónustur","þjónustu","þjónustunnar"]},{"id":"uptime","g":"run","word":"Uppitímaathugun","text":"Sjálfvirk athugun, á fárra mínútna fresti, at þjónusta þín svari enn. Ef hon bregzk mörgum sinnum í röð, opnar AI-gile atviksspjald af sjálfu sér.","also":["uppitími","uppitímaathuganir","uptime"]},{"id":"statuspage","g":"run","word":"Stöðusíða","text":"Opinber síða er sýnir hvárt þjónusta virki (grænt, rauðgult eða rautt) með hinum nýjustu tíðindum, svá at þeir er nota hana megi líta á í stað þess at spyrja.","also":["stöðusíður","stöðusíðu","stöðusíðunni"]},{"id":"desk","g":"run","word":"Þjónustuborð","text":"Þar er spurningar ok tilkynningar koma inn frá þeim er nota þjónustu þína. AI-gile flokkar hverja sem beiðni, atvik eða hugmynd, ok segir til ef hon líkisk nökkuru er áðr var tilkynnt.","also":["þjónustuborð","hjálparborð","helpdesk"]},{"id":"svcrequest","g":"run","word":"Þjónustubeiðni","text":"Einhverr biðr um nökkut hversdagsligt, svá sem nýjan reikning eða litla hjálp, en tilkynnir eigi at nökkut sé brotit. Hon bíðr síns tíma; atvik gengr fyrst.","also":["þjónustubeiðnir"]},{"id":"incident","g":"run","word":"Atvik","text":"Nökkut er brotit fyrir þá er nota þat nú þegar, svá sem at vefsetrit sé niðri. 🔥 Atviksspjald hleypr fram fyrir röðina: at koma því í lag aftr gengr fyrst.","also":["atviki","atviks","atvikum","atviksspjald"]},{"id":"major","g":"run","word":"Stórt atvik","text":"Mikit atvik: margir menn snortnir, eða fé eða gögn í hættu. Einn hnappr setr hverja sveit á þat (sveimr), vekr þann er á vakt er ok biðr um stöðufregn á hverjum 30 mínútum.","also":["stór atvik","stóru atviki"]},{"id":"oncall","g":"run","word":"Vakt","text":"At vera sá er svarar þá er nökkut brotnar, jafnvel um nótt. Hver þjónusta hefir sveitarmann á vakt er vakinn er fyrst við atvik hennar.","also":["á vakt","vaktmaðr","vaktar","on-call"]},{"id":"replyby","g":"run","word":"Svarfrestr","text":"Hversu lengi spjald má bíða fyrsta svars, t.d. eina stund fyrir atvik. Eptir þat fær þat rauða klukku, svá at ekkert gleymisk í kyrrþey. Kallask ok svarmark.","also":["svarfrest","svarfrestir","svarmark"]},{"id":"postmortem","g":"run","word":"Eftirrannsókn","text":"Stutt endrlit eptir atvik: hvat gerðisk, hvat hjálpaði ok hverju skal breyta, án þess at kenna nökkurum um. Atviki má eigi loka án hennar.","also":["eftirrannsóknir","eftirrannsókn","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Vandamál","text":"Hin hulda sök at baki eins eða fleiri atvika. 🧩 Vandamálsspjald safnar saman atvikum er koma sí ok æ aftr, svá at sökin finnisk ok lagisk um alla tíð.","also":["vandamáls","vandamálum","vandamálsspjald"],"noTip":1},{"id":"rootcause","g":"run","word":"Rótarsök","text":"Hin sanna ástæða þess at nökkut brotnaði, eigi aðeins þat er þú sátt fara illa. Laga rótarsökina, ok atvikit hættir at koma aftr.","also":["rótarsakir","rótarsakar"]},{"id":"workaround","g":"run","word":"Undankoma","text":"Leið til at halda hlutum í gangi unz hin sanna lagfæring er búin, svá sem at ræsa nökkut aftr þá er þat festisk. Hon er rituð á vandamálsspjaldit, svá at engi þurfi at finna hana aftr.","also":["undankomu","undankomur","úrræði"]},{"id":"knownerror","g":"run","word":"Kunn villa","text":"Vandamál er sökin er skilin ok undankoma til, en eigi enn lagat. 🧩 Kunnar villur telja þær upp, svá at allir noti undankomuna í stað þess at grafa aftr.","also":["kunnar villur","kunna villu"]},{"id":"runbook","g":"run","word":"Leiðbeiningabók","text":"Skref fyrir skref leiðsögn til at laga kunna tegund vandræða, svá at þat sé gert á sama hátt, skjótt, hvert sinn. Eptir stórt atvik má sveitin leggja eina til, ok þú gefr OK.","also":["leiðbeiningabækr","leiðbeiningabókar","runbook","runbooks"]},{"id":"ci","g":"run","word":"Stillingarhlutr","text":"Einn hlutr er þjónusta þín treystir á, svá sem netþjónn, lén, skírteini, lykill eða birgir. 🗂️ Stillingarhlutir telja þá upp fyrir hverja þjónustu, svá at þú sér hvat atvik snertir ok hvat þarf endrnýjun eða afrit.","also":["stillingarhlutir"]},{"id":"expiry","g":"run","word":"Gildislok","text":"AI-gile hefir auga á dögum, svá sem nær skírteini eða lén rennr út. Innan 30 daga fyrir daginn gerir þat eitt spjald til at endrnýja, svá at ekki hættir at virka óvænt.","also":["lokadagar","gildistími","gætsla gildisloka"]},{"id":"backup","g":"run","word":"Afrit","text":"Vistat eintak gagna þinna frá fyrri tíð, at grípa til ef nökkut týnisk eða spillisk. AI-gile gerir afrit af töflum þínum hvern dag.","also":["afriti","afrits","afritum","backup"]},{"id":"restore","g":"run","word":"Endrheimt","text":"At setja gögn aftr af afriti. Afrit telsk eigi sannliga fyrr en þú veizt at þat má endrheimta, því er vert at reyna þat stundum.","also":["endrheimta","endrheimt","endrheimtr"]},{"id":"svcreview","g":"run","word":"Þjónustuendrskoðun","text":"Litit aftr yfir einn mánuð þjónustu: atvik opnuð ok lagfærð, hversu skjótt menn fengu svar, uppitími ok tákn notuð. Mánaðarleg endrskoðun sýnir þat fyrir hverja þjónustu.","also":["þjónustuendrskoðanir","mánaðarleg endrskoðun","mánaðarligar endrskoðanir"]},{"id":"accessreview","g":"run","word":"Aðgangsendrskoðun","text":"Athugun hvern 90. dag á því hverr enn kemsk inn: deilitenglar, hlutverk vina ok geymd leyndarmál. Þú heldr eða fjarlægir hvert, svá at gamall aðgangr hangi eigi eftir.","also":["aðgangsendrskoðanir"]},{"id":"improvements","g":"run","word":"Úrbótaskrá","text":"Allt er sveitin ákvað at bæta, á einum stað: tillögur úr retro, aðgerðir úr endrskoðunum ok lagfæringar vandamála, hvert með stöðu sinni. Finn hana undir 📈 Úrbætr.","also":["úrbótaskrár","úrbætr"]},{"id":"tokencap","g":"run","word":"Táknamark","text":"Mánaðarmark á táknum er erindrekar þjónustu mega nota. Við 80% fær þú viðvörun; við 100% bíðr bakgrunnsverk þeirra til næsta mánaðar eða unz þú hækkar markit.","also":["táknamörk"]},{"id":"backlog","g":"team","word":"Backlog","text":"Hugmyndir ok starf sem eigi er enn áætlat. Ekkert þar er unnit unz þat flyzt í Til gerðar."},{"id":"sprint","g":"team","word":"Sprint","text":"Stutt starfahrina (oft vika eða tvær) með ákveðnu safni spjalda til at ljúka.","also":["sprints"]},{"id":"standup","g":"team","word":"Fundr","text":"Skjót yfirheyrsla: hvat hverr liðsmaðr gerði, hvat hann gerir næst, ok hvat tálmar honum.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Borð með dálkum (Til gerðar, Í verki, Lokit) þar er spjöld flytjask frá vinstri til hægri er starf gerisk."},{"id":"wip","g":"team","word":"WIP-mark","text":"Work in progress: flest spjöld er dálkr skal geyma, svá at sveitin ljúki hlutum áðr en hún hefr fleiri.","also":["WIP"]},{"id":"dod","g":"team","word":"Skilgreining um Lokit","text":"Stuttr gátlisti sveitarinnar um hvat „lokit“ merkir, svá sem prófat ok skýrt, áðr en spjald er fengit þér. Tvíburi hans, Skilgreining um Búit, segir nær spjald er nógu ljóst til at hefja.","also":["Skilgreining um Búit","Definition of Done","Definition of Ready"]},{"id":"testpile","g":"team","word":"Prófhlaði","text":"Lokin spjöld er bíða at þú reynir þau, eitt eptir annat. Samþykk eitt eða send þat aftr með athugasemd, ok hit næsta kemr upp.","also":["prófhlaða","prófhlaðar"]},{"id":"retro","g":"team","word":"Endrlit","text":"Litit aftr á hversu sveitin starfar, til at sættask á einn hlut at gera betr. Í AI-gile leggr endrlit til breytingu á starfsháttum sveitarinnar, ok þú segir Gakk eða Eigi enn.","also":["endrliti","endrlits","retro","retrospective"]},{"id":"peerreview","g":"team","word":"Jafningjaskoðun","text":"Annat augnapar: önnur gervigreind athugar verk hvers spjalds áðr en þat nær þér, svá at færri villur sleppi í gegn.","also":["jafningjaskoðunar","kóðaskoðun","peer review","code review"]},{"id":"swarm","g":"team","word":"Sveimr","text":"Allar hendr á þilfar: hver sveit leggr annat verk frá sér til at hjálpa við eitt brátt verkefni unz þat er leyst. Önnur verkefni bíða meðan.","also":["sveim","sverm","swarm"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Sá er heldr verkinu á ferð: sér föst spjöld, ýtir við sveitunum ok minnir þik á hvat bíðr. Í AI-gile gerir Aðalfundarstjórinn þetta yfir öll verkefni.","also":["Aðalfundarstjóri","fundarstjóri","Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Gervigreind er starfar sjálf at verki: les kóðann, gerir breytingar, rennir athuganir ok segir frá.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Eining er notkun gervigreindar er talin í: nokkurn veginn fáir stafir lesnir eða ritaðir. Færri tákn, meira eftir af áætlun þinni.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Lítil skipun er rennr sjálf á ákveðnu augnabliki, t.d. þá er gervigreindarseta hefst, svá at sveitin heyri ummæli þín.","also":["hooks"]}]}};
